from dataclasses import dataclass
from datetime import date, timedelta

MAX_RENEWALS = 2
LOAN_PERIOD_DAYS = 21
DAILY_FINE_CENTS = 25
GRACE_DAYS = 3


@dataclass
class Hold:
    patron_id: str
    isbn: str
    position: int
    placed_on: date


@dataclass
class Loan:
    patron_id: str
    isbn: str
    due_date: date
    renewed: int = 0


class LendingDesk:
    def __init__(self):
        self.holds = []
        self.loans = []
        self.balances = {}

    def place_hold(self, patron_id, isbn):
        existing = [h for h in self.holds if h.isbn == isbn]
        next_position = len(existing) + 1
        hold = Hold(patron_id=patron_id, isbn=isbn, position=next_position, placed_on=date.today())
        self.holds.append(hold)
        return hold

    def cancel_hold(self, patron_id, isbn):
        target = next(
            (h for h in self.holds if h.patron_id == patron_id and h.isbn == isbn),
            None,
        )
        if target is None:
            return
        self.holds.remove(target)
        for hold in self.holds:
            if hold.isbn == isbn and hold.position > target.position:
                hold.position += 1
        self.holds.sort(key=lambda h: (h.isbn, h.position))

    def next_in_line(self, isbn):
        candidates = [h for h in self.holds if h.isbn == isbn]
        if not candidates:
            return None
        return min(candidates, key=lambda h: h.position)

    def assess_return_fine(self, patron_id, isbn, returned_on):
        loan = next(
            (l for l in self.loans if l.patron_id == patron_id and l.isbn == isbn),
            None,
        )
        if loan is None:
            return 0
        days_late = (returned_on - loan.due_date).days - GRACE_DAYS
        if days_late <= 0:
            self.loans.remove(loan)
            return 0
        fine = days_late * DAILY_FINE_CENTS
        self.balances[patron_id] = self.balances.get(patron_id, 0) + fine
        self.loans.remove(loan)
        return fine

    def renew_loan(self, patron_id, isbn):
        loan = next(
            (l for l in self.loans if l.patron_id == patron_id and l.isbn == isbn),
            None,
        )
        if loan is None or loan.renewed >= MAX_RENEWALS:
            return None
        if any(h.isbn == isbn for h in self.holds):
            return None
        loan.due_date = loan.due_date + timedelta(days=LOAN_PERIOD_DAYS)
        loan.renewed += 1
        return loan.due_date
